using Microsoft.AspNetCore.Components;

namespace sv_311c14f27bae4f4fbe79ddfabdb610f1.Components;

public class RedirectToLogin : ComponentBase
{
    [Inject]
    private NavigationManager Navigation { get; set; } = default!;

